<?php

$stdin = fopen('php://stdin', 'r');

$line1 = trim(fgets($stdin));
$parts1 = explode(' ', $line1);
$a = (int)$parts1[0];
$ta = (int)$parts1[1];

$line2 = trim(fgets($stdin));
$parts2 = explode(' ', $line2);
$b = (int)$parts2[0];
$tb = (int)$parts2[1];

$timeStr = trim(fgets($stdin));
list($h, $m) = explode(':', $timeStr);
$h = (int)$h;
$m = (int)$m;

$depart = $h * 60 + $m;
$arrive = $depart + $ta;

$startB = 5 * 60;
$endB = 23 * 60 + 59;

$low = $depart - $tb;
$high = $arrive;

$low_bound = max($low, $startB);
$high_bound = min($high, $endB);

if ($low_bound >= $high_bound) {
    echo 0 . "\n";
    exit;
}

$first = ceil($low_bound / $b) * $b;
$last = floor(($high_bound - 1) / $b) * $b;

if ($first > $last) {
    echo 0 . "\n";
} else {
    $count = (int)(($last - $first) / $b) + 1;
    echo $count . "\n";
}

fclose($stdin);

